#include "EqGraph.h"
#include "../dsp/BiquadCascade.h"
static juce::String bandId(int b,const char* field){return "b"+juce::String(b+1)+"_"+field;}
void EqGraph::edit(int b,const char* name,float value){if(auto* p=processor.state.getParameter(bandId(b,name))){p->beginChangeGesture();p->setValueNotifyingHost(p->convertTo0to1(value));p->endChangeGesture();}}
int EqGraph::hit(juce::Point<float> pos) const{auto b=processor.bands();for(int i=7;i>=0;--i)if(b[i].enabled&&pos.getDistanceFrom({xFromFreq((float)b[i].freq),yFromGain((float)b[i].gain)})<18.f)return i;return -1;}
void EqGraph::paint(juce::Graphics& g){auto w=(float)getWidth(),h=(float)getHeight();g.setColour(Theme::dim.withAlpha(.32f));for(int k=-18;k<=18;k+=6){float y=yFromGain((float)k);g.setColour(Theme::dim.withAlpha(k==0?.7f:.35f));g.drawHorizontalLine((int)y,0,w);}
 for(int d=1;d<=10000;d*=10)for(int m=1;m<=9;++m){float f=(float)(d*m);if(f<20||f>20000)continue;float x=xFromFreq(f);g.setColour(Theme::dim.withAlpha((m==1||m==2||m==5)?.38f:.15f));g.drawVerticalLine((int)x,0,h);}
 // Spectrum is displayed in a fixed -90..0 dB range, lightly smoothed in timerCallback.
 juce::Path area;area.startNewSubPath(0,h);for(int i=0;i<256;++i){float x=w*i/255.f;float y=h*(1.f-juce::jlimit(0.f,1.f,(spectrum[i]+90.f)/90.f));area.lineTo(x,y);}area.lineTo(w,h);area.closeSubPath();g.setColour(Theme::green.withAlpha(.17f*processor.state.getRawParameterValue("analyzeAmount")->load()/100.f));g.fillPath(area);
 auto bands=processor.bands();int slope=1+(int)processor.state.getRawParameterValue("slope")->load();juce::Path response;for(int i=0;i<650;++i){float x=w*i/649.f;double f=freqFromX(x);std::complex<double> r{1,0};for(auto& b:bands)r*=SkellyDSP::bandResponse(b,f,processor.sampleRateHz(),slope);float db=(float)juce::Decibels::gainToDecibels(std::abs(r),-100.0);float y=yFromGain(juce::jlimit(-18.f,18.f,db));if(i==0)response.startNewSubPath(x,y);else response.lineTo(x,y);}
 g.setColour(Theme::green.withAlpha(.13f));g.strokePath(response,juce::PathStrokeType(13.f));g.setColour(Theme::glow.withAlpha(.22f));g.strokePath(response,juce::PathStrokeType(6.f));g.setColour(Theme::green);g.strokePath(response,juce::PathStrokeType(2.8f));
 for(int i=0;i<8;++i){if(!bands[i].enabled)continue;auto x=xFromFreq((float)bands[i].freq),y=yFromGain((float)bands[i].gain);g.setColour(Theme::green.withAlpha(.20f));g.fillEllipse(x-17,y-17,34,34);g.setColour(i==selected?Theme::amber:Theme::text);g.drawEllipse(x-10,y-10,20,20,2.4f);g.setColour(Theme::bg);g.fillEllipse(x-6,y-6,12,12);g.setColour(Theme::green);g.fillEllipse(x-3,y-3,6,6);}
}
void EqGraph::mouseDown(const juce::MouseEvent& e){if(e.mods.isPopupMenu()){int i=hit(e.position);if(i>=0){selected=i;if(selectionChanged)selectionChanged();juce::PopupMenu menu;menu.addItem(1,"Peak");menu.addItem(2,"Low Shelf");menu.addItem(3,"High Shelf");menu.addItem(4,"Low Cut");menu.addItem(5,"High Cut");menu.addItem(6,"Notch");menu.addItem(7,"Band Pass");menu.addSeparator();menu.addItem(10,"Toggle bypass");menu.addItem(11,"Solo");menu.addItem(12,"Delete band");juce::Component::SafePointer<EqGraph> safe(this);menu.showMenuAsync(juce::PopupMenu::Options(),[safe,i](int choice){if(!safe||!choice)return;if(choice<=7)safe->edit(i,"type",(float)(choice-1));else if(choice==10)safe->edit(i,"enabled",safe->processor.bands()[i].enabled?0.f:1.f);else if(choice==11)safe->edit(i,"solo",safe->processor.bands()[i].solo?0.f:1.f);else if(choice==12)safe->edit(i,"enabled",0.f);});}return;}
 dragging=hit(e.position);startPoint=e.position;if(dragging>=0){selected=dragging;auto b=processor.bands()[dragging];startFreq=(float)b.freq;startGain=(float)b.gain;startQ=(float)b.q;if(selectionChanged)selectionChanged();}}
void EqGraph::mouseDrag(const juce::MouseEvent& e){if(dragging<0)return;auto d=e.position-startPoint;float fine=e.mods.isShiftDown()?.15f:1.f;if(e.mods.isAltDown()){edit(dragging,"q",juce::jlimit(.1f,18.f,startQ*std::exp(-d.y*fine*.012f)));return;}
 if(!e.mods.isCtrlDown()||std::abs(d.x)>std::abs(d.y))edit(dragging,"freq",freqFromX(xFromFreq(startFreq)+d.x*fine));
 if(!e.mods.isCtrlDown()||std::abs(d.y)>=std::abs(d.x))edit(dragging,"gain",gainFromY(yFromGain(startGain)+d.y*fine));}
void EqGraph::mouseUp(const juce::MouseEvent&){dragging=-1;}
void EqGraph::mouseDoubleClick(const juce::MouseEvent& e){int i=hit(e.position);if(i>=0){edit(i,"enabled",0);return;}auto b=processor.bands();for(i=0;i<8;++i)if(!b[i].enabled){edit(i,"freq",freqFromX(e.position.x));edit(i,"gain",gainFromY(e.position.y));edit(i,"enabled",1);selected=i;if(selectionChanged)selectionChanged();break;}}
void EqGraph::mouseWheelMove(const juce::MouseEvent& e,const juce::MouseWheelDetails& d){int i=hit(e.position);if(i>=0)edit(i,"q",juce::jlimit(.1f,18.f,(float)(processor.bands()[i].q*std::exp(d.deltaY*.12f))));}
void EqGraph::mouseMove(const juce::MouseEvent& e){int i=hit(e.position);if(i>=0){auto b=processor.bands()[i];setTooltip(juce::String(b.freq,1)+" Hz  "+juce::String(b.gain,1)+" dB  Q "+juce::String(b.q,2));}else setTooltip({});}
void EqGraph::timerCallback(){if(processor.state.getRawParameterValue("analyzeMode")->load()==0){spectrum.fill(-90);repaint();return;}std::array<float,4096> incoming{};int got=processor.analyzer.pop(incoming.data(),1024);if(got){if(filled+got>4096){auto move=filled+got-4096;std::memmove(time.data(),time.data()+move,sizeof(float)*(filled-move));filled-=move;}std::copy_n(incoming.begin(),got,time.begin()+filled);filled+=got;}
 if(filled>=4096){std::copy(time.begin(),time.end(),spectrumData.begin());std::fill(spectrumData.begin()+4096,spectrumData.end(),0);window.multiplyWithWindowingTable(spectrumData.data(),4096);fft.performFrequencyOnlyForwardTransform(spectrumData.data());double sr=processor.sampleRateHz();for(int i=0;i<256;++i){float f=20.f*std::pow(1000.f,i/255.f);int bin=juce::jlimit(1,2047,(int)(f*4096/sr));float magnitude=spectrumData[bin]/2048.f;float db=juce::Decibels::gainToDecibels(magnitude,-90.f);float speed=db>spectrum[i]?.40f:.11f;spectrum[i]+=(db-spectrum[i])*speed;}std::memmove(time.data(),time.data()+1024,3072*sizeof(float));filled=3072;}repaint();}
